  KEY `idx_user_keyword` (`user_id`,`normalized_keyword`),
  KEY `idx_session_keyword` (`session_id`,`normalized_keyword`),
  KEY `idx_user_created` (`user_id`,`created_at`),
  KEY `idx_session_created` (`session_id`,`created_at`)
