  `entity_id` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci NOT NULL COMMENT 'ID of the entity (product ID, supplier ID, category ID, search query)',
  `entity_name` varchar(500) CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT 'Name/title of the entity for display',
  `metadata` json DEFAULT NULL COMMENT 'Additional metadata (supplierId, categoryId, resultsCount, etc.)',
  `time_spent_seconds` int DEFAULT '0' COMMENT 'Time spent in seconds (for time_spent interactions)',
  `created_at` timestamp NULL DEFAULT CURRENT_TIMESTAMP COMMENT 'When the interaction occurred',
  PRIMARY KEY (`id`),
  KEY `idx_user_id` (`user_id`),
  KEY `idx_session_id` (`session_id`),
  KEY `idx_entity` (`entity_type`,`entity_id`),
  KEY `idx_created_at` (`created_at`),
  KEY `idx_interaction_type` (`interaction_type`),
  KEY `idx_user_session` (`user_id`,`session_id`),
  KEY `idx_entity_interaction` (`entity_type`,`entity_id`,`interaction_type`),
  KEY `idx_user_entity_type` (`user_id`,`entity_type`,`created_at`),
  KEY `idx_session_entity_type` (`session_id`,`entity_type`,`created_at`),
  KEY `idx_user_interactions_category` (`user_id`,`entity_type`,`entity_id`,`created_at`),
  KEY `idx_user_interactions_supplier` (`user_id`,`entity_type`,`entity_id`,`created_at`),
  KEY `idx_user_interactions_product` (`user_id`,`entity_type`,`entity_id`,`created_at`)
) ENGINE=InnoDB AUTO_INCREMENT=185998 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='Detailed interaction log for all users (logged-in and anonymous)';

